import{_ as t,o,c as a,ag as i}from"./chunks/framework.D5hoimZQ.js";const _=JSON.parse('{"title":"科学日报 · 2026-09-15（生物医学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-09-15.md","filePath":"topics/biomedicine/science-daily-2026-09-15.md"}'),r={name:"topics/biomedicine/science-daily-2026-09-15.md"};function n(l,e,s,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="科学日报-·-2026-09-15-生物医学" tabindex="-1">科学日报 · 2026-09-15（生物医学） <a class="header-anchor" href="#科学日报-·-2026-09-15-生物医学" aria-label="Permalink to &quot;科学日报 · 2026-09-15（生物医学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-15.md</code> — 第26期</p></blockquote><hr><h2 id="tri-611-可入脑的-alk-分子胶降解剂对抗耐药肺癌-nature" tabindex="-1">TRI-611：可入脑的 ALK 分子胶降解剂对抗耐药肺癌（Nature） <a class="header-anchor" href="#tri-611-可入脑的-alk-分子胶降解剂对抗耐药肺癌-nature" aria-label="Permalink to &quot;TRI-611：可入脑的 ALK 分子胶降解剂对抗耐药肺癌（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-15.md</code> ｜ DOI: 10.1038/s41586-026-10998-3</p></blockquote><ul><li>背景：靶向 ALK 的 TKI 已重塑 ALK 融合阳性 NSCLC 治疗，但对已批准 TKI 进展者选择有限，需正交策略（耐药 + 脑转移）。</li><li>TRI-611：强效、<strong>可透过血脑屏障</strong>的分子胶降解剂。通过远离激酶活性位点的独特 degron 界面，拉近 ALK 激酶结构域与 CRL4 底物受体 CRBN 的邻近 → 把 ALK 融合蛋白送入泛素-蛋白酶体降解。</li><li>特点：独特结合界面带来<strong>全蛋白质组选择性</strong>（含已知 CRBN neosubstrates 与其他激酶）；能降解<strong>所有形式</strong> ALK 融合蛋白（含野生型与 TKI 耐药版），驱动细胞系与病人来源<strong>皮下/颅内</strong>肿瘤模型退缩。</li><li>洞察：<strong>&quot;降解而非抑制&quot;</strong> 对耐药 + 中枢转移尤为关键 —— 分子胶向&quot;可入脑的靶向降解&quot;拓展，衔接本主题靶向蛋白降解 / 耐药肺癌主线。</li></ul><h2 id="前列腺癌突变印记整合-八类足印解释-85-原发基因组-nature" tabindex="-1">前列腺癌突变印记整合：八类足印解释 85% 原发基因组（Nature） <a class="header-anchor" href="#前列腺癌突变印记整合-八类足印解释-85-原发基因组-nature" aria-label="Permalink to &quot;前列腺癌突变印记整合：八类足印解释 85% 原发基因组（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-15.md</code> ｜ DOI: 10.1038/s41586-026-10468-w</p></blockquote><ul><li>前列腺癌病程长、异质、病因未明。样本：泛前列腺癌工作组 <strong>959 例</strong> 供体基因组。</li><li>整合从头提取的 SBS / 插入缺失 / 拷贝数印记 + 六个新的<strong>复杂结构变异印记</strong> → 识别出八个整合突变足印（IMF），<strong>共同解释 85%</strong> 原发前列腺癌基因组。</li><li>IMF 明显受基因组区域偏差影响，最突出的是<strong>雄激素受体介导的突变发生</strong>与复制应激；其中四个 IMF（见于 37% 原发肿瘤）与<strong>更短的到转移时间</strong>显著相关（含活性氧驱动的突变发生等）。</li><li>洞察：把不同类别突变信号&quot;整合成足印&quot;来给肿瘤<strong>分子分型 + 风险分层</strong> —— 对治疗时机选择有直接转化意义，与基因组学/肿瘤进化认知相关。</li></ul>',9)])])}const p=t(r,[["render",n]]);export{_ as __pageData,p as default};
